using System;
using System.Collections;
using UnityEngine;
namespace NoiteSemFim {
public sealed partial class SurvivorGame {
 // Preparation precedes release; recovery starts only after the power is released.
 static readonly float[] powerPreparationTimes={.22f,.16f,.45f,.40f,.50f,.30f};
 readonly float[] powerPreparation=new float[6];
 readonly bool[] preparingPower=new bool[6];
 bool orbitPowerReady;
 SpriteRenderer powerPreparationHalo;
 float PowerPreparationTime(int id)=>SignatureWeapon(id)?(WeaponArchetype==3?.10f:WeaponArchetype==4?.48f:.28f):powerPreparationTimes[id];
 int PreparingPowerId {get{int best=-1;float remaining=float.MaxValue;for(int i=0;i<6;i++)if(preparingPower[i]&&powerPreparation[i]<remaining){best=i;remaining=powerPreparation[i];}return best;}}
 float PowerRange(int id){int rank=Mathf.Max(1,weapons[id]);if(SignatureWeapon(id)&&HasAttackRelic)return WeaponArchetype==3?10:WeaponArchetype==4?6:10;if(SignatureWeapon(id)&&WeaponArchetype!=5)return (WeaponArchetype==4?2.65f:1.8f)*Area+rank*.06f;if(id==2)return (1.5f+rank*.1f)*Area+.55f*Area;if(id==5)return (.55f+rank*.05f)*5+.35f*Area;return 10;}
 Enemy PowerTarget(int id){Enemy best=null;float distance=float.MaxValue;float range=PowerRange(id);foreach(var e in enemies){float d=(e.p-pos).sqrMagnitude;float reach=range+(IsBoss(e.type)?.8f:.35f);if(e.hp>0&&d<=reach*reach&&d<distance){distance=d;best=e;}}return best;}
 bool CanPreparePower(int id)=>PowerTarget(id)!=null&&(!manualAim||ManualAttackHeld||manualAttackRequested[id]||preparingPower[id]||id==2&&manualCrownRemaining>0);
 void BeginPowerPreparation(int id){preparingPower[id]=true;powerPreparation[id]=PowerPreparationTime(id);}
 void CancelPowerPreparation(){Array.Clear(preparingPower,0,6);Array.Clear(powerPreparation,0,6);if(powerPreparationHalo!=null)powerPreparationHalo.enabled=false;}
 void ResetPowerPreparation(){ResetManualAttack();CancelPowerPreparation();powerPreparationHalo=null;orbitPowerReady=false;}
 void UpdatePowerPreparationVisual(){int id=PreparingPowerId;if(id<0){if(powerPreparationHalo!=null)powerPreparationHalo.enabled=false;return;}float progress=1-Mathf.Clamp01(powerPreparation[id]/PowerPreparationTime(id));var color=Catalog.Colors[id];color.a=.45f+progress*.35f;if(powerPreparationHalo==null)powerPreparationHalo=Sprite("Preparing Power",ArtBank.Ring,pos,.8f,color,Depth(pos)-1);powerPreparationHalo.enabled=true;powerPreparationHalo.transform.position=pos;powerPreparationHalo.transform.localScale=Vector3.one*Mathf.Lerp(.7f,1.25f,progress);powerPreparationHalo.sortingOrder=Depth(pos)-1;powerPreparationHalo.color=color;}
 void DrawPowerPreparationSlot(int id,float x,float y,float size){if(!preparingPower[id])return;float progress=1-Mathf.Clamp01(powerPreparation[id]/PowerPreparationTime(id));Rect(x+6,y+6,size-12,size-12,new Color(.02f,.12f,.17f,.66f));Text(powerPreparation[id].ToString("0.0")+"s",x+5,y+11,size-10,24,Style(13,cyan,TextAnchor.MiddleCenter,true));Rect(x+6,y+size-11,size-12,4,new Color(.07f,.15f,.18f));Rect(x+6,y+size-11,(size-12)*progress,4,cyan);}
 // Advance real weapon simulation in small steps, without skipping preparation in QA.
 void AdvanceWeaponsForCheck(float duration){while(duration>.00001f){float step=Mathf.Min(.01f,duration);UpdateWeapons(step);duration-=step;}}
 string VerifyPowerPreparation(){var account=save;bool oldVerify=verifying,oldAim=manualAim;int oldHero=heroIndex,oldDragon=selectedDragon,oldCurse=selectedCurse;verifying=true;save=new SaveData();heroIndex=0;selectedDragon=selectedCurse=-1;manualAim=true;
  foreach(int weapon in new[]{0,1,3,4,5}){StartRun();Array.Clear(weapons,0,6);weapons[weapon]=1;manualAimPoint=Vector2.right*4;lastAimDirection=Vector2.right;var target=SpawnEnemy(0,false);target.p=weapon==3?Vector2.right:weapon==5?Vector2.right*3:Vector2.right*4;target.hp=target.maxHp=10000;float startHp=target.hp;int beforeEffects=effects.Count;UpdateWeapons(.001f);if(!preparingPower[weapon]||shots.Count!=0||effects.Count!=beforeEffects||target.hp!=startHp)throw new Exception("Power fired before preparation "+weapon);AdvanceWeaponsForCheck(PowerPreparationTime(weapon)-.02f);if(!preparingPower[weapon]||shots.Count!=0||target.hp!=startHp)throw new Exception("Power preparation too short "+weapon);state=ScreenState.Paused;float remaining=powerPreparation[weapon];Update();if(powerPreparation[weapon]!=remaining)throw new Exception("Paused preparation advanced");state=ScreenState.Playing;AdvanceWeaponsForCheck(.025f);if(preparingPower[weapon]||cooldown[weapon]<=0)throw new Exception("Power failed to release "+weapon);if(weapon==0||weapon==1||weapon==3||weapon==5){if(shots.Count==0)throw new Exception("Prepared projectile missing "+weapon);}else if(target.hp>=startHp)throw new Exception("Prepared area damage missing "+weapon);int releasedShots=shots.Count,releasedEffects=effects.Count;AdvanceWeaponsForCheck(.1f);if(shots.Count!=releasedShots||effects.Count!=releasedEffects)throw new Exception("Power repeated during recovery "+weapon);}
  StartRun();Array.Clear(weapons,0,6);weapons[2]=1;var crownTarget=SpawnEnemy(0,false);crownTarget.p=Vector2.right*1.6f;crownTarget.hp=10000;UpdateWeapons(.001f);AdvanceWeaponsForCheck(.40f);if(orbitPowerReady||orbitVisuals.Count>0)throw new Exception("Crown activated without preparation");AdvanceWeaponsForCheck(.06f);if(!orbitPowerReady||orbitVisuals.Count==0)throw new Exception("Crown activation failed");AdvanceWeaponsForCheck(.6f);if(preparingPower[2]||!orbitPowerReady)throw new Exception("Crown repeatedly charged after activation");
  StartRun();Array.Clear(weapons,0,6);weapons[0]=1;manualAim=false;var near=SpawnEnemy(0,false);near.p=Vector2.left;UpdateWeapons(.01f);enemies.Clear();AdvanceWeaponsForCheck(.3f);if(shots.Count!=0)throw new Exception("Dead automatic target caused ghost shot");manualAim=true;var replacement=SpawnEnemy(0,false);replacement.p=Vector2.right*3;replacement.hp=10000;cooldown[0]=0;manualAimPoint=Vector2.left*3;UpdateWeapons(.01f);manualAimPoint=Vector2.right*3;AdvanceWeaponsForCheck(.23f);if(shots.Count==0||shots[0].v.x<=0)throw new Exception("Prepared manual power did not use latest cursor");
  Array.Clear(weapons,0,6);weapons[1]=1;cooldown[1]=0;UpdateWeapons(.01f);EndRun(false);if(PreparingPowerId!=-1||powerPreparationHalo!=null&&powerPreparationHalo.enabled)throw new Exception("Preparation survived result");StartRun();if(PreparingPowerId!=-1||orbitPowerReady)throw new Exception("Preparation leaked into new run");
  StartRun();for(int i=0;i<6;i++)weapons[i]=1;var final=SpawnEnemy(4,true);final.p=Vector2.right;final.hp=1;manualAimPoint=Vector2.right;AdvanceWeaponsForCheck(.6f);if(state!=ScreenState.Result||PreparingPowerId!=-1)throw new Exception("Victory started another preparation");save=account;heroIndex=oldHero;selectedDragon=oldDragon;selectedCurse=oldCurse;manualAim=oldAim;verifying=oldVerify;ReturnMenu();return "Power preparation: per-ability delay, no early damage/projectiles, single release, recovery, pause freeze, one-time crown activation, target loss, live manual aim, result cancellation and run reset PASS.";
 }
 IEnumerator CapturePowerPreparation(string folder){bool aim=manualAim;int oldHero=heroIndex;heroIndex=0;manualAim=true;StartRun();elementPreviewFrozen=true;Array.Clear(weapons,0,6);for(int i=0;i<6;i++)weapons[i]=1;manualAimPoint=Vector2.right*4;lastAimDirection=Vector2.right;UpdateWeapons(.01f);AdvanceWeaponsForCheck(.08f);AnimateHero(.01f,Vector2.zero);yield return Capture(folder,"poderes-preparando-v11");AdvanceWeaponsForCheck(.45f);UpdateShots(.1f);yield return Capture(folder,"poderes-ativados-v11");elementPreviewFrozen=false;manualAim=aim;heroIndex=oldHero;ReturnMenu();}
}
}
